import Foundation
import DORMEKit

/// The robot's wiring, exploded (Resources/robot_wiring.json, generated by cad/app_model/wiring_export.py from the
/// wiring table and the CAD's routed wire tubes). One entry per conductor, with its real end points, pin names,
/// colour and gauge. PRELIMINARY like the wiring table: it shows the design, not a robot that has been wired.
struct Wiring: Decodable {
    struct End: Decodable {
        let part: String?
        let layer: String
        let pin: String
        let text: String
        let joint: String
        let p: [Double]
    }
    struct Wire: Decodable, Identifiable {
        let id: String
        let label: String
        let name: String
        let net: String
        let kind: String
        let color: [Double]
        let d: Double
        let awg: String
        let from: End
        let to: End
        let pair: String?
        let points: [[Double]]
    }
    struct PartInfo: Decodable {
        let layer: String
        let offset: [Double]
        let ghost: Bool
        let hide: Bool
    }
    let parts: [String: PartInfo]
    let wires: [Wire]
    let mates: [[[Double]]]

    static let shared: Wiring? = {
        guard let url = Bundle.main.url(forResource: "robot_wiring", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Wiring.self, from: data)
    }()

    func wire(_ id: String) -> Wire? { wires.first { $0.id == id } }

    /// Conductors that end on a part.
    func wires(of part: String) -> [Wire] {
        let k = PartKey.norm(part)
        return wires.filter { PartKey.norm($0.from.part ?? "") == k || PartKey.norm($0.to.part ?? "") == k }
    }
}

/// What a part or a wire is doing right now, in plain words, from the robot's live state. Nothing here is invented:
/// where the robot has no sensor the text says so (no wheel speed, no motor current, no 6.3 V rail reading).
@MainActor
enum LiveStatus {
    struct Text {
        var title: String
        var lines: [String]
    }

    private static func live(_ store: RobotStore) -> RobotState? {
        store.phase == .connected || store.isDemo ? store.state : nil
    }

    private static func v(_ x: Double?, _ digits: Int = 1) -> String? { x.map { String(format: "%.\(digits)f V", $0) } }

    private static func pct(_ pwm: Int?) -> Int? { pwm.map { Int((Double($0) / 255 * 100).rounded()) } }

    private static func dirWord(_ d: String?) -> String? {
        switch d {
        case "F", "FF": return "forward"
        case "B", "RR": return "backward"
        case "L", "RF": return "turning left"
        case "R", "FR": return "turning right"
        default: return nil
        }
    }

    /// The left side runs forward when DORM-E goes forward or turns right; the right side when it goes forward or left.
    private static func sideDir(_ s: Signals?, left: Bool) -> String? {
        guard let d = s?.dir, d.count == 2 else { return nil }
        let c = left ? d.first! : d.last!
        return c == "F" ? "forward" : "backward"
    }

    private static func drive(_ st: RobotState, left: Bool) -> (pct: Int?, dir: String?) {
        let s = st.signals
        let p = pct(left ? s?.pwmL : s?.pwmR)
        if let p, p > 0 { return (p, sideDir(s, left: left)) }
        if st.motion.state == "moving", s == nil { return (nil, dirWord(st.motion.direction)) }
        return (0, nil)
    }

    static func part(_ id: String, store: RobotStore) -> Text {
        let key = PartKey.norm(id)
        let name = PartCatalog.name(id)
        guard let st = live(store) else {
            return Text(title: name, lines: [whatItIs(key), "Connect to DORM-E to see what it is doing right now."].filter { !$0.isEmpty })
        }
        let sig = st.signals
        let bench = st.motion.outputs == "disabled_bench"
        let battery = v(st.battery.voltageV)
        var lines: [String] = []
        switch key {
        case "pi4":
            lines.append("Running DORM-E's software and talking to the ESP32 over USB (\(st.connection.esp32 == "up" ? "linked, status 10 times a second" : "not linked"))."
            )
            lines.append("Drawing the face on the screen (\(st.face.state == "screen" ? "your own screen" : "face: " + (st.screen?.face?.style ?? "classic")))." )
            let cam = st.peripherals.camera.status
            lines.append(cam == "available" || cam == "simulated" ? "Camera ready; video goes to the app when you open it." : "Camera not connected.")
            if let ssid = st.network.wifiSsid {
                lines.append("On Wi-Fi \u{201C}\(ssid)\u{201D}\(st.network.wifiDbm.map { " at \($0) dBm" } ?? "").")
            }
            if let t = st.health?.part("PI4")?.t { lines.append("Chip temperature: \(t).") }
            lines.append("Microphones: not listening yet (voice control isn't connected).")
        case "esp32u7":
            if st.connection.esp32 != "up" {
                lines.append("Not linked to the Pi (\(st.connection.esp32)). It keeps the motors stopped on its own.")
                break
            }
            let l = drive(st, left: true), r = drive(st, left: false)
            if bench {
                lines.append("Bench mode: it keeps motor power off and sends no drive signal.")
            } else if (l.pct ?? 0) == 0 && (r.pct ?? 0) == 0 {
                lines.append("Holding both motor drivers at 0 % (stopped).")
            } else {
                lines.append("Sending the left driver \(l.pct.map { "\($0) %" } ?? "a") PWM \(l.dir ?? "") and the right driver \(r.pct.map { "\($0) %" } ?? "a") PWM \(r.dir ?? "").")
            }
            if let on = sig?.motorsEnabled { lines.append("Motor enable (GPIO23): \(on ? "on" : "off").") }
            if let vb = sig?.vbusV ?? st.battery.voltageV { lines.append("Reading the battery at \(String(format: "%.2f", vb)) V from the INA219 over I2C.") }
            if let cm = sig?.sonarCm ?? st.peripherals.sonar.distanceCm { lines.append("Pinging the sonar: \(cm) cm to the nearest thing ahead.") }
            lines.append("Reporting all of this to the Pi 10 times a second\(st.connection.hbGapMaxMs.map { "; longest gap \($0) ms" } ?? "").")
            if let f = st.fault.active { lines.append("Holding a safety stop: \(f.title).") }
        case "md20au4", "md20au5":
            let left = key == "md20au4"
            let d = drive(st, left: left)
            let side = left ? "left" : "right"
            if bench { lines.append("Bench mode: no drive signal, motors off.") }
            else if let p = d.pct, p > 0 {
                lines.append("Getting \(p) % PWM \(d.dir ?? "") from the ESP32 (\(left ? "GPIO25" : "GPIO26")) and driving the \(side) motors (\(left ? "M1, M2" : "M3, M4")) with it.")
            } else { lines.append("Idle: the ESP32 is sending 0 % PWM, so the \(side) motors are off.") }
            lines.append("Powered from the \(side) 6.3 V rail (\(left ? "U2" : "U3")); its current is not measured.")
        case "m1", "m2", "m3", "m4":
            let left = key == "m1" || key == "m2"
            let d = drive(st, left: left)
            if bench { lines.append("Off (bench mode).") }
            else if let p = d.pct, p > 0 { lines.append("Being driven \(d.dir ?? "") at \(p) % power by the \(left ? "left" : "right") MD20A.") }
            else { lines.append("Stopped.") }
            lines.append("There is no speed or current sensor on the motors, so how fast it actually turns isn't measured.")
        case "w1", "w2", "w3", "w4":
            let left = key == "w1" || key == "w2"
            let d = drive(st, left: left)
            if !bench, let p = d.pct, p > 0 {
                lines.append("Turning \(d.dir ?? "") with its motor at \(p) % power (commanded).")
                if let c = st.motion.owner?.direction.flatMap { dirWord($0) } { lines.append("DORM-E is \(c == "forward" || c == "backward" ? "driving " + c : c).") }
            } else { lines.append("Not turning.") }
            lines.append("No wheel sensor: the actual speed and distance are not measured.")
        case "battery":
            lines.append("Supplying \(battery ?? "an unknown voltage")\(st.battery.underLoad ? " (under load)" : "").")
            lines.append(st.battery.percent == nil ? "Percentage isn't shown until the battery is calibrated." : "")
            if st.power.plug == true { lines.append("Charger plugged in.") }
        case "ina219u9":
            if let vb = sig?.vbusV ?? st.battery.voltageV {
                lines.append("Measuring the logic rail at \(String(format: "%.2f", vb)) V and sending it to the ESP32 over I2C.")
            } else { lines.append("No reading right now.") }
        case "sonar":
            if let cm = sig?.sonarCm ?? st.peripherals.sonar.distanceCm { lines.append("Measuring \(cm) cm to the nearest thing in front, 10 times a second.") }
            else { lines.append(st.peripherals.sonar.reason ?? "No echo.") }
        case "u15":
            lines.append(st.power.motorRailOn == true ? "Motor power on\(st.power.motorRailV.map { String(format: ", %.1f V", $0) } ?? "")." : "Motor power off.")
        case "u14":
            lines.append("On: passing battery power to the rest of the robot (the Pi is running, so it must be).")
        case "xl4005u2", "xl4005u3":
            let on = st.power.motorRailOn == true
            lines.append(on ? "Stepping the motor power down to about 6.3 V for the \(key == "xl4005u2" ? "left" : "right") driver." : "No input: motor power is off.")
            lines.append("The 6.3 V output is set at build and not measured live.")
        case "u1":
            lines.append("Making 5 V for the Pi (USB-C) and for the sonar, fan and logic (aux).")
            if let t = st.health?.part("U1"), t.s == "fault" { lines.append(t.t) }
        case "fusef0", "fusef1":
            lines.append("Intact: the Pi is running, and its power comes through this fuse.")
        case "fusef2", "fusef3":
            lines.append(st.power.motorRailOn == true ? "Carrying motor power to the \(key == "fusef2" ? "left" : "right") side (no sensor on the fuse itself)." : "Idle: motor power is off.")
        case "fusef4":
            lines.append(st.power.plug == true ? "Charger plugged in: protects the charge path." : "Idle: no charger plugged in.")
        case "dcb":
            lines.append("Keeps DORM-E switched on (U13), gates motor power (Q2) and senses the switch and the charge plug.")
            if let p = st.power.plug { lines.append(p ? "Charge plug: in." : "Charge plug: out.") }
            if let s = st.health?.part("S2_SWITCH")?.t { lines.append("Button: \(s.lowercased()).") }
        case "lcd":
            switch st.face.state {
            case "screen": lines.append("Showing your screen: \u{201C}\(st.screen?.custom?.label ?? "custom")\u{201D}.")
            case "note": lines.append("Showing your message: \u{201C}\(st.screen?.note?.text ?? "")\u{201D}.")
            case "pairing": lines.append("Showing a pairing code.")
            default:
                if let r = st.screen?.resting { lines.append("Showing your resting screen \u{201C}\(r.label ?? "")\u{201D}.") }
                else { lines.append("Showing the face (\(st.screen?.face?.style ?? "classic"), \(st.face.state)).") }
            }
            lines.append("Tap it to edit what it shows.")
        case "camera":
            let s = st.peripherals.camera.status
            lines.append(s == "available" || s == "simulated" ? "Ready. Sends video to the Pi when the app's camera view is open." : (st.peripherals.camera.reason ?? "Not connected."))
        case "csiribbon":
            lines.append("Carries the camera's video to the Pi.")
        case "audiou16":
            lines.append(st.peripherals.audio.isUsable ? "Detected by the Pi. Its microphones aren't used yet." : "Not detected.")
        case "speaker":
            lines.append("Silent: sound playback isn't connected yet.")
        case "fan", "fanctrl":
            lines.append("Cooling the inside from the 5 V aux rail (no speed sensor).")
        case "s2switch":
            lines.append(st.health?.part("S2_SWITCH")?.t == "On" ? "On (its ring is lit yellow)." : (st.health?.part("S2_SWITCH")?.t ?? "No data"))
        case "jchg":
            lines.append(st.power.plug == true ? "Charger plugged in." : "No charger plugged in.")
        case "k2relay", "th1":
            lines.append(st.power.plug == true ? "Charge path: charger present." : "Charge path idle (no charger).")
        case "star":
            lines.append("Every ground wire meets here; return current from the whole robot flows through it.")
        case "j1batt":
            lines.append("Battery plugged in\(battery.map { ", \($0)" } ?? "").")
        case "motorrailparts":
            lines.append(st.power.motorRailOn == true ? "Smoothing the 6.3 V motor rails and catching voltage spikes." : "Idle: motor power is off.")
        default:
            break
        }
        let what = whatItIs(key)
        return Text(title: name, lines: ([what] + lines).filter { !$0.isEmpty })
    }

    static func whatItIs(_ key: String) -> String {
        switch key {
        case "pi4": return "The brain: runs the app connection, face, camera and tasks."
        case "esp32u7": return "The motor and safety controller."
        case "md20au4", "md20au5": return "Motor driver: turns the ESP32's PWM signal into motor power."
        case "dcb": return "DORM-E's own control board."
        case "ina219u9": return "Voltage monitor."
        case "u1": return "5 V power supply."
        case "u14": return "Main power switch (MOSFET)."
        case "u15": return "Motor power switch (MOSFET)."
        case "xl4005u2", "xl4005u3": return "Step-down converter for one side's motors."
        case "a01chassis", "a02tray", "a03cover", "a04bezel", "a05hatch", "a06barleft", "a07barright": return "Printed part."
        default: return ""
        }
    }

    // MARK: Wires

    static func wire(_ w: Wiring.Wire, store: RobotStore) -> Text {
        let from = "\(PartCatalog.name(w.from.part ?? w.from.layer.capitalized + " plug")) \(w.from.pin)"
        let to = "\(PartCatalog.name(w.to.part ?? w.to.layer.capitalized + " plug")) \(w.to.pin)"
        var lines = ["\(from) \u{2192} \(to)", gauge(w)]
        if let st = live(store) { lines.append(now(w, st)) } else { lines.append(about(w)) }
        return Text(title: "\(w.name) (\(w.label))", lines: lines)
    }

    private static func gauge(_ w: Wiring.Wire) -> String {
        switch w.kind {
        case "usb": return "USB cable."
        case "jumper": return "Jumper wire with Dupont ends."
        case "twisted": return "\(w.awg) AWG, twisted pair."
        default: return w.awg.allSatisfy(\.isNumber) ? "\(w.awg) AWG wire." : "Lead."
        }
    }

    private static func about(_ w: Wiring.Wire) -> String {
        "Net \(w.net). Connect to DORM-E to see its live value."
    }

    private static func now(_ w: Wiring.Wire, _ st: RobotState) -> String {
        let net = w.net.uppercased()
        let s = st.signals
        let bat = st.battery.voltageV
        let railOn = st.power.motorRailOn == true
        if net.contains("GND") || net.contains("STAR") || net.contains("B1-") || net.contains("RETURN") {
            return "Ground (0 V): the return path back to the star point."
        }
        if net.hasPrefix("PWM_") {
            let left = net.hasSuffix("L")
            if let p = pct(left ? s?.pwmL : s?.pwmR) { return "Now: \(p) % PWM (\(left ? s?.pwmL ?? 0 : s?.pwmR ?? 0) of 255)." }
            return "PWM speed signal to the motor driver; no fresh reading."
        }
        if net.hasPrefix("DIR_") {
            let d = sideDir(s, left: net.hasSuffix("L"))
            return d.map { "Direction signal: \($0)." } ?? "Direction signal; not driving now."
        }
        if net.hasPrefix("MOT_L") || net.hasPrefix("MOT_R") {
            let dr = drive(st, left: net.hasPrefix("MOT_L"))
            if let p = dr.pct, p > 0 { return "Motor power, switched at \(p) % \(dr.dir ?? ""). Current is not measured." }
            return "No motor power right now."
        }
        if net.contains("6V3") || net.contains("6.30") || net.contains("MOTOR RAIL") {
            return railOn ? "About 6.3 V (set at build; not measured live)." : "Off: motor power is switched off."
        }
        if net.contains("VBAT_MOT") || net.contains("F2 OUT") || net.contains("F3 OUT") || net == "MOT_SENSE" {
            return railOn ? "Motor supply\(st.power.motorRailV.map { String(format: ", %.1f V", $0) } ?? "")." : "Off: the motor switch is open."
        }
        if net.contains("VBAT") || net.contains("B1+") || net.contains("VF_CTL") {
            return "Battery power\(bat.map { String(format: ", about %.1f V", $0) } ?? "")."
        }
        if net.contains("+5V_USB") { return "5 V for the Pi." }
        if net.contains("+5V_AUX") { return "5 V for the sonar, fan and logic." }
        if net.contains("U7_3V3") { return "3.3 V from the ESP32's regulator." }
        if net.hasPrefix("I2C") { return "I2C: carries the INA219's voltage reading to the ESP32." }
        if net.hasPrefix("TRIG") { return "Trigger pulses to the sonar, 10 times a second." }
        if net.hasPrefix("ECHO") {
            return (s?.sonarCm ?? st.peripherals.sonar.distanceCm).map { "Echo from the sonar: \($0) cm." } ?? "Echo from the sonar; no reading."
        }
        if net == "MOT_EN" { return s.map { "Motor enable: \($0.motorsEnabled ? "on" : "off")." } ?? "Motor enable; no reading." }
        if net == "PLUG_SENSE" || net.contains("CHG") || net.contains("CHARGE") || net == "T1_SENSE" {
            return st.power.plug == true ? "Charger plugged in." : "Charge path idle (no charger)."
        }
        if net == "GPIO32" || net == "RUN_N" { return "Reads the button: \(st.health?.part("S2_SWITCH")?.t.lowercased() ?? "unknown")." }
        if net == "GPIO33" { return st.power.shuttingDown == nil ? "Kill line idle: DORM-E stays on." : "Shutting down." }
        if net == "EN_N" || net == "U15_SW" { return "Switch control line." }
        if net.contains("USB") { return w.to.part == "ESP32_U7" || w.from.part == "ESP32_U7" ? "Serial link: status and commands between the Pi and the ESP32." : "USB." }
        if net.contains("SPK") || net.contains("SPEAKER") { return "No sound playing (playback isn't connected yet)." }
        return "Net \(w.net)."
    }
}
